import os
import re

violations = []

for root, dirs, files in os.walk('.'):
    for file in files:
        if not file.endswith('.py'):
            continue
        filepath = os.path.join(root, file)

        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                lines = f.readlines()

            # Track set creations
            for i, line in enumerate(lines, 1):
                # Check for set comprehensions or set() calls
                if re.search(r'=\s*set\(|=\s*frozenset\(|\{[^}]*for[^}]*in[^}]*\}', line):
                    # Check if this flows to JSON within next 20 lines
                    context = ''.join(lines[i:min(i+20, len(lines))])
                    if 'to_json' in context or 'json.dumps' in context or 'return {' in context:
                        # Check if set is sorted before output
                        if 'sorted(' not in context and '.pop()' not in context:
                            if re.search(r'for .* in.*\}|set\(.*for', line):
                                violations.append(f"{filepath}:{i}: {line.strip()}")
        except Exception as e:
            pass

if violations:
    for v in violations:
        print(v)
else:
    print("No violations found!")
EOF
